insert into public.mentorship_records (record_key, title, category, summary, method, outcome, is_public, sort_order)
values
('candidate-assessment','Candidate Assessment','candidate-assessment','Evaluated technical candidates beyond surface-level syntax knowledge by considering engineering judgment, role fit, ownership, learning ability, and practical execution.','Used work-sample discussion, reasoning questions, delivery scenarios, and role-specific technical review without recording private identities or confidential hiring feedback.','Several referred candidates were later described by colleagues as useful, competent, and effective contributors.',true,0),
('private-mentorship','Private Mentorship','private-mentorship','Privately mentored high-potential junior developers who had not yet reached their practical capability.','Focused on technical fundamentals, debugging, implementation discipline, project execution, professional judgment, and career positioning.',null,true,1),
('intern-development','Intern Development','intern-development','Developed software engineering interns through task ownership, implementation review, technical guidance, and delivery accountability.','Assigned bounded production-oriented work, reviewed implementation decisions, and used structured feedback to increase independent ownership.',null,true,2)
